#include <stdio.h>
#include <string.h>

/* 爬楼梯: 每次上 1 或 2 级, 求 n 级台阶的方案数
   演示两种 DP 范式: 自顶向下备忘录 与 自底向上填表 */
long long memo[100];

/* 自顶向下备忘录: 先查表, 未计算则递归求解并存储 */
long long climb_memo(int n) {
    if (n <= 2) return n;               /* 基础情形: 1 级 1 种, 2 级 2 种 */
    if (memo[n] != -1) return memo[n];  /* 重叠子问题: 直接返回已存结果 */
    memo[n] = climb_memo(n - 1) + climb_memo(n - 2);
    return memo[n];
}

/* 自底向上: 按规模从小到大递推, 无递归调用 */
long long climb_dp(int n) {
    long long a = 1, b = 2;             /* f(1) = 1, f(2) = 2 */
    if (n == 1) return 1;
    for (int i = 3; i <= n; i++) {
        long long t = a + b;
        a = b;
        b = t;
    }
    return b;
}

int main(void) {
    int n;
    printf("请输入台阶数 n (1~90): ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 90) {
        printf("输入无效!\n");
        return 1;
    }
    memset(memo, -1, sizeof(memo));     /* -1 表示尚未计算 */
    printf("自顶向下备忘录: %lld\n", climb_memo(n));
    printf("自底向上 DP   : %lld\n", climb_dp(n));
    return 0;
}

# 爬楼梯: 每次上 1 或 2 级, 求 n 级台阶的方案数
# 演示两种 DP 范式: 自顶向下备忘录 与 自底向上填表

def climb_memo(n, memo=None):
    # 自顶向下备忘录: 先查表, 未计算则递归求解并存储
    if memo is None:
        memo = {}
    if n <= 2:
        return n
    if n not in memo:
        memo[n] = climb_memo(n - 1, memo) + climb_memo(n - 2, memo)
    return memo[n]

def climb_dp(n):
    # 自底向上: f(1) = 1, f(2) = 2, f(i) = f(i-1) + f(i-2)
    if n <= 2:
        return n
    a, b = 1, 2
    for _ in range(3, n + 1):
        a, b = b, a + b
    return b

n = int(input("请输入台阶数 n (1~90): "))
print("自顶向下备忘录:", climb_memo(n))
print("自底向上 DP   :", climb_dp(n))

