/* 钢条切割: r[n] = max(p[i] + r[n-i]), 自底向上 + 重构切割方案 */
int main(void) {
    int n, p[100], r[101], s[101];
    printf("请输入钢条长度 n (1~99): ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 99) {
        printf("输入无效!\n");
        return 1;
    }
    printf("请输入 1~%d 长度的价格(共 %d 个整数): ", n, n);
    for (int i = 1; i <= n; i++) scanf("%d", &p[i]);

    r[0] = 0;                            /* 长度为 0 的收益为 0 */
    for (int i = 1; i <= n; i++) {       /* 自底向上: 长度从小到大 */
        int best = -1;
        for (int j = 1; j <= i; j++) {   /* 第一段切 j, 收益 p[j] + r[i-j] */
            if (p[j] + r[i - j] > best) {
                best = p[j] + r[i - j];
                s[i] = j;                /* 记录最优首段长度 */
            }
        }
        r[i] = best;
    }
    printf("最大收益: %d\n", r[n]);
    printf("切割方案: ");
    for (int len = n; len > 0; len -= s[len]) printf("%d ", s[len]);
    printf("\n");
    return 0;
}

#include <stdio.h>

/* 矩阵链乘法: m[i][j] = min(m[i][k] + m[k+1][j] + p[i-1]*p[k]*p[j])
   按链长递增填表, s[i][j] 记录最优分裂点, 递归构造括号化 */
#define MAXN 30
#define INF ((long long)1 << 60)

long long m[MAXN + 1][MAXN + 1];
int s[MAXN + 1][MAXN + 1];

void print_chain(int i, int j) {        /* 递归输出最优括号化 */
    if (i == j) { printf("A%d", i); return; }
    printf("(");
    print_chain(i, s[i][j]);
    print_chain(s[i][j] + 1, j);
    printf(")");
}

int main(void) {
    int n, p[MAXN + 1];
    printf("请输入矩阵个数 n (1~30): ");
    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN) {
        printf("输入无效!\n");
        return 1;
    }
    printf("请输入维度 p[0..n] 共 %d 个整数: ", n + 1);
    for (int i = 0; i <= n; i++) scanf("%d", &p[i]);

    for (int i = 1; i <= n; i++) m[i][i] = 0;      /* 单矩阵代价 0 */
    for (int len = 2; len <= n; len++) {           /* 链长递增 */
        for (int i = 1; i <= n - len + 1; i++) {
            int j = i + len - 1;
            m[i][j] = INF;
            for (int k = i; k < j; k++) {
                long long c = m[i][k] + m[k + 1][j]
                            + (long long)p[i - 1] * p[k] * p[j];
                if (c < m[i][j]) { m[i][j] = c; s[i][j] = k; }
            }
        }
    }
    printf("最小标量乘法次数: %lld\n", m[1][n]);
    printf("最优括号化: ");
    print_chain(1, n);
    printf("\n");
    return 0;
}

