/* LCS: 最长公共子序列, 两分支递推 + 表构造 + 回溯输出 */
#define MAXL 1000
int dp[MAXL + 1][MAXL + 1];
char a[MAXL + 1], b[MAXL + 1];

void print_lcs(int i, int j) {          /* 回溯输出一个 LCS */
    if (i == 0 || j == 0) return;
    if (a[i - 1] == b[j - 1]) {         /* 相等: 该字符属于 LCS, 斜走 */
        print_lcs(i - 1, j - 1);
        putchar(a[i - 1]);
    } else if (dp[i - 1][j] >= dp[i][j - 1]) {   /* 走向较大的邻居 */
        print_lcs(i - 1, j);
    } else {
        print_lcs(i, j - 1);
    }
}

int main(void) {
    printf("请输入两个字符串(不含空格, 长度 <= %d):\n", MAXL);
    if (scanf("%s %s", a, b) != 2) { printf("输入无效!\n"); return 1; }
    int n = strlen(a), m = strlen(b);

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (a[i - 1] == b[j - 1])
                dp[i][j] = dp[i - 1][j - 1] + 1;
            else
                dp[i][j] = dp[i - 1][j] > dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1];
        }
    }
    printf("LCS 长度: %d\n", dp[n][m]);
    printf("一个 LCS: ");
    print_lcs(n, m);
    printf("\n");
    return 0;
}

# LCS: 最长公共子序列, 两分支递推 + 表构造 + 回溯输出
import sys

def lcs_table(a, b):
    n, m = len(a), len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp

def backtrace(dp, a, b):
    # 从右下角回溯: 相等斜走, 否则走向 dp 值较大的邻居
    i, j = len(a), len(b)
    res = []
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            res.append(a[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1
    return "".join(reversed(res))

data = sys.stdin.read().split()
a, b = data[0], data[1]
dp = lcs_table(a, b)
print("LCS 长度:", dp[len(a)][len(b)])
print("一个 LCS:", backtrace(dp, a, b))

