/* LIS: 贪心 + 二分 O(n log n)
   d[i] 维护长度为 i 的递增子序列的最小尾元素
   last[p] 记录 d[p] 当前对应的原下标, 用于重构一个 LIS */
#define MAXN 100000
static int a[MAXN], d[MAXN + 1], last[MAXN + 1], pre[MAXN];

int main(void) {
    int n;
    printf("请输入元素个数 n (1~%d): ", MAXN);
    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN) {
        printf("输入无效!\n");
        return 1;
    }
    printf("请输入 %d 个整数: ", n);
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);

    int len = 0;                          /* d 的当前长度 */
    for (int i = 0; i < n; i++) {
        /* 在 d[1..len] 中二分找第一个 >= a[i] 的位置 p */
        int lo = 1, hi = len, p = len + 1;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (d[mid] >= a[i]) { p = mid; hi = mid - 1; }
            else lo = mid + 1;
        }
        d[p] = a[i];                      /* 替换或追加 */
        last[p] = i;                      /* 记录该位置对应的原下标 */
        pre[i] = (p > 1) ? last[p - 1] : -1;  /* 前驱: 长度为 p-1 时对应的元素 */
        if (p > len) len = p;
    }

    /* 重构: 从 last[len] 沿 pre 链回溯 */
    int k = last[len], stack[MAXN], top = 0;
    while (k != -1) { stack[top++] = a[k]; k = pre[k]; }
    printf("LIS 长度: %d\n", len);
    printf("一个 LIS: ");
    while (top > 0) printf("%d ", stack[--top]);
    printf("\n");
    return 0;
}

