/* 0-1 背包: 二维 DP 表 + 方案回溯
   dp[i][j] = max(dp[i-1][j], dp[i-1][j-w[i]] + v[i])
   注释中说明如何滚动为一维(逆序遍历) */
#define MAXN 100
#define MAXW 10000
static int dp[MAXN + 1][MAXW + 1];

int main(void) {
    int n, W, w[MAXN + 1], v[MAXN + 1];
    printf("请输入物品数 n 与背包容量 W: ");
    if (scanf("%d %d", &n, &W) != 2 || n < 1 || n > MAXN || W < 0 || W > MAXW) {
        printf("输入无效!\n");
        return 1;
    }
    printf("请依次输入每件物品的重量与价值(w v):\n");
    for (int i = 1; i <= n; i++) scanf("%d %d", &w[i], &v[i]);

    /* 二维填表: 第 i 轮只依赖第 i-1 行, 可滚动为一行;
       滚动为一维时容量必须逆序: for j = W..w[i] 更新 dp[j] */
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= W; j++) {
            dp[i][j] = dp[i - 1][j];                  /* 不选第 i 件 */
            if (j >= w[i] && dp[i - 1][j - w[i]] + v[i] > dp[i][j])
                dp[i][j] = dp[i - 1][j - w[i]] + v[i]; /* 选第 i 件 */
        }
    }
    printf("最大价值: %d\n", dp[n][W]);

    /* 回溯方案: 从 (n, W) 逆推 */
    printf("选取方案: ");
    for (int i = n, j = W; i >= 1; i--) {
        if (j >= w[i] && dp[i][j] == dp[i - 1][j - w[i]] + v[i]) {
            printf("%d ", i);
            j -= w[i];
        }
    }
    printf("\n");
    return 0;
}

