/* 完全背包(一维正序) 与 多重背包(二进制拆分) 演示 */
#define MAXW 10000
static int dp[MAXW + 1];

int main(void) {
    int type, n, W, w[101], v[101], c[101];
    printf("请输入背包类型(1=完全, 2=多重) 物品数n 容量W: ");
    if (scanf("%d %d %d", &type, &n, &W) != 3 || n < 1 || n > 100 || W > MAXW) {
        printf("输入无效!\n");
        return 1;
    }
    printf("请依次输入每件物品的重量 价值 (多重背包还需 数量):\n");
    for (int i = 1; i <= n; i++) {
        if (type == 2) scanf("%d %d %d", &w[i], &v[i], &c[i]);
        else scanf("%d %d", &w[i], &v[i]);
    }

    memset(dp, 0, sizeof(dp));
    if (type == 1) {
        /* 完全背包: 正序, 同一物品可反复取 */
        for (int i = 1; i <= n; i++)
            for (int j = w[i]; j <= W; j++)
                if (dp[j - w[i]] + v[i] > dp[j]) dp[j] = dp[j - w[i]] + v[i];
    } else {
        /* 多重背包: 二进制拆分后按 0-1(逆序) 处理 */
        for (int i = 1; i <= n; i++) {
            int cnt = c[i];
            for (int k = 1; cnt > 0; k <<= 1) {
                int take = (k < cnt) ? k : cnt;   /* 拆出 1,2,4,...,剩余 */
                cnt -= take;
                for (int j = W; j >= take * w[i]; j--)   /* 0-1 逆序 */
                    if (dp[j - take * w[i]] + take * v[i] > dp[j])
                        dp[j] = dp[j - take * w[i]] + take * v[i];
            }
        }
    }
    printf("最大价值: %d\n", dp[W]);
    return 0;
}

