/* 编辑距离: 插入/删除/替换 递推 + 路径回溯输出编辑过程 */
#define MAXL 1000
static int dp[MAXL + 1][MAXL + 1];
static char ops[3000][32];             /* 记录编辑操作, 每步至多一次 */
static char a[MAXL + 1], b[MAXL + 1];

int main(void) {
    printf("请输入两个字符串(不含空格, 长度 <= %d):\n", MAXL);
    if (scanf("%s %s", a, b) != 2) { printf("输入无效!\n"); return 1; }
    int n = strlen(a), m = strlen(b);

    for (int i = 0; i <= n; i++) dp[i][0] = i;   /* 全删 */
    for (int j = 0; j <= m; j++) dp[0][j] = j;   /* 全插 */
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            int cost = (a[i - 1] == b[j - 1]) ? 0 : 1;   /* 替换代价 */
            int d = dp[i - 1][j] + 1;             /* 删除 a[i] */
            int ins = dp[i][j - 1] + 1;           /* 插入 b[j] */
            int rep = dp[i - 1][j - 1] + cost;    /* 匹配或替换 */
            dp[i][j] = d < ins ? d : ins;
            if (rep < dp[i][j]) dp[i][j] = rep;
        }
    }
    printf("编辑距离: %d\n", dp[n][m]);

    /* 回溯: 先收集到 ops 数组, 再逆序输出(得到从前往后的编辑过程) */
    int cnt = 0, i = n, j = m;
    while (i > 0 || j > 0) {
        if (i > 0 && j > 0 && a[i - 1] == b[j - 1] && dp[i][j] == dp[i - 1][j - 1]) {
            sprintf(ops[cnt++], "保留 %c", a[i - 1]); i--; j--;
        } else if (i > 0 && j > 0 && dp[i][j] == dp[i - 1][j - 1] + 1) {
            sprintf(ops[cnt++], "替换 %c -> %c", a[i - 1], b[j - 1]); i--; j--;
        } else if (i > 0 && dp[i][j] == dp[i - 1][j] + 1) {
            sprintf(ops[cnt++], "删除 %c", a[i - 1]); i--;
        } else {
            sprintf(ops[cnt++], "插入 %c", b[j - 1]); j--;
        }
    }
    printf("编辑过程(从前到后):\n");
    for (int k = cnt - 1; k >= 0; k--) printf("  %s\n", ops[k]);
    return 0;
}

