/* 石子合并(线性): 区间 DP 模板
   dp[i][j] = min(dp[i][k] + dp[k+1][j]) + sum(i, j), 按区间长度递增 */
#define MAXN 300
#define INF 0x3f3f3f3f
static int a[MAXN + 1], sum[MAXN + 1], dp[MAXN + 1][MAXN + 1];

int main(void) {
    int n;
    printf("请输入石子堆数 n (1~%d): ", MAXN);
    if (scanf("%d", &n) != 1 || n < 1 || n > MAXN) {
        printf("输入无效!\n");
        return 1;
    }
    printf("请输入每堆石子数: ");
    sum[0] = 0;
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        sum[i] = sum[i - 1] + a[i];      /* 前缀和: O(1) 求区间和 */
    }

    memset(dp, 0x3f, sizeof(dp));        /* INF 初始化 */
    for (int i = 1; i <= n; i++) dp[i][i] = 0;   /* 单堆代价 0 */
    for (int len = 2; len <= n; len++) {         /* 区间长度递增 */
        for (int i = 1; i + len - 1 <= n; i++) {
            int j = i + len - 1;
            for (int k = i; k < j; k++) {
                int c = dp[i][k] + dp[k + 1][j] + sum[j] - sum[i - 1];
                if (c < dp[i][j]) dp[i][j] = c;
            }
        }
    }
    printf("最小合并代价: %d\n", dp[1][n]);
    return 0;
}
